let activeEffect = null
const bucket = new WeakMap() // target -> Map<key, Set<effect>>
function track(target, key) {
  if (!activeEffect) return
  let depsMap = bucket.get(target)
  if (!depsMap) bucket.set(target, (depsMap = new Map()))
  let dep = depsMap.get(key)
  if (!dep) depsMap.set(key, (dep = new Set()))
  dep.add(activeEffect) // Set 天然去重
  activeEffect.deps.push(dep)
}
function trigger(target, key) {
  const dep = bucket.get(target)?.get(key)
  if (!dep) return
  ;[...dep].forEach((fn) => { if (fn !== activeEffect) fn() })
}
const proxyMap = new WeakMap()
function reactive(target) {
  if (proxyMap.has(target)) return proxyMap.get(target) // 复用代理
  const proxy = new Proxy(target, {
    get(t, k, r) {
      track(t, k)
      const v = Reflect.get(t, k, r)
      return typeof v === 'object' && v !== null ? reactive(v) : v // 懒代理
    },
    set(t, k, v, r) {
      const had = Object.prototype.hasOwnProperty.call(t, k)
      const old = t[k]
      const ok = Reflect.set(t, k, v, r)
      if (!had || old !== v) trigger(t, k)
      return ok
    },
  })
  proxyMap.set(target, proxy)
  return proxy
}
function effect(fn) {
  const effectFn = () => {
    for (const d of effectFn.deps) d.delete(effectFn) // cleanup 防分支残留
    effectFn.deps = []
    const prev = activeEffect
    activeEffect = effectFn
    try { return fn() } finally { activeEffect = prev }
  }
  effectFn.deps = []
  effectFn()
  return effectFn
}

